package com.harvestflow.registration.service.impl;
import com.harvestflow.registration.entity.*; import com.harvestflow.registration.exception.*; import com.harvestflow.registration.repository.OtpChallengeRepository; import com.harvestflow.registration.service.OtpService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.security.SecureRandom; import java.time.Instant; import java.util.UUID;
@Service
public class DefaultOtpService implements OtpService {
 private final OtpChallengeRepository repo; private final PasswordEncoder encoder; private final SecureRandom random=new SecureRandom();
 public DefaultOtpService(OtpChallengeRepository repo,PasswordEncoder encoder){this.repo=repo;this.encoder=encoder;}
 public void sendOtp(UUID id,OtpPurpose purpose,String destination){repo.findTopByRegistrationSessionIdAndPurposeOrderByCreatedAtDesc(id,purpose).filter(x->x.getConsumedAt()==null).ifPresent(x->{if(Instant.now().isBefore(x.getCreatedAt().plusSeconds(30)))throw new RegistrationException("Please wait before requesting another OTP");});String otp=String.format("%06d",random.nextInt(1_000_000));OtpChallenge c=new OtpChallenge();c.setRegistrationSessionId(id);c.setPurpose(purpose);c.setOtpHash(encoder.encode(otp));c.setExpiresAt(Instant.now().plusSeconds(300));repo.save(c);throw new RegistrationException("OTP delivery provider is not configured");}
 public void verifyOtp(UUID id,OtpPurpose purpose,String otp){OtpChallenge c=repo.findTopByRegistrationSessionIdAndPurposeOrderByCreatedAtDesc(id,purpose).orElseThrow(()->new OtpInvalidException("No OTP was requested"));if(c.getConsumedAt()!=null)throw new OtpAlreadyConsumedException("OTP already used");if(Instant.now().isAfter(c.getExpiresAt()))throw new OtpExpiredException("OTP expired");if(c.getAttemptCount()>=5)throw new TooManyOtpAttemptsException("Too many incorrect attempts, request a new OTP");c.setAttemptCount(c.getAttemptCount()+1);if(!encoder.matches(otp,c.getOtpHash())){repo.save(c);throw new OtpInvalidException("Incorrect OTP");}c.setConsumedAt(Instant.now());repo.save(c);}
}
